    "write": [
     {
      "id": "hidden-alone",
      "rule": "描画に出さないなら、hidden: true だけを書く。",
      "why": "ほかのキーと一緒に書くと、出すのか出さないのかが決まらない。",
      "test": "hidden がある x-view に、ほかのキーが無いかを見る。",
      "by": "machine"
     }
    ]
   }
  },
  "prompt": {
   "type": "object",
   "description": "x-prompt。read は値の読み方を観点ごとに、write は書くときの決まりを1件ずつ持つ",
   "required": [
    "read",
    "write"
   ],
   "additionalProperties": false,
   "properties": {
    "read": {
     "$ref": "#/$defs/reading"
    },
    "write": {
     "type": "array",
     "minItems": 1,
     "items": {
      "$ref": "#/$defs/rule"
     }
    }
   }
  },
  "reading": {
   "type": "object",
   "description": "値の読み方。観点ごとに1文",
   "required": [
    "means"
   ],
   "additionalProperties": false,
   "properties": {
    "means": {
     "$ref": "#/$defs/sentence",
     "description": "何を表すか"
    },
    "shown": {
     "$ref": "#/$defs/sentence",
     "description": "どこにどう出るか"
    },
    "parse": {
     "$ref": "#/$defs/sentence",
     "description": "値をどう解くか"
    },
    "when": {
     "$ref": "#/$defs/sentence",
     "description": "いつ、何のために読むか"
    }
   }
  },
  "rule": {
   "type": "object",
   "description": "書くときの決まり1件",
   "required": [
    "id",
    "rule",
    "why",
    "test"
   ],
   "additionalProperties": false,
   "properties": {
    "id": {
     "type": "string",
     "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
    },
    "rule": {
     "$ref": "#/$defs/sentence"
    },
    "why": {
     "$ref": "#/$defs/sentence"
    },
    "test": {
     "$ref": "#/$defs/sentence"
    },
    "by": {
     "$ref": "urn:semantic-schema-core:annotations:v1#/$defs/judge",
     "description": "この決まりを判定する者。書かなければ unsupported と返る"
    },
    "requires": {
     "type": "array",
     "items": {
      "type": "string",
      "minLength": 1
     },
     "description": "validator に必要な capability"
    },
    "required": {
     "type": "boolean",
     "description": "検証できなければ全体を成功にしない決まりか"
    },
    "bad": {
     "type": "string",
     "minLength": 1
    },
    "good": {
     "type": "string",
     "minLength": 1
    }
   },
   "dependentRequired": {
    "bad": [
     "good"
    ],
    "good": [
     "bad"
    ]
   }
  },
  "sentence": {
   "type": "string",
   "minLength": 1,
   "maxLength": 120
  }
 }
